ss=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$177,250 CAD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Why Join Dialpad&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
